# Nav + Hero + Features + Quote + Pricing + CTA + Footer, all on design tokens,
# with the tension elements embedded (2px quote border, accent pricing tier,
# asymmetric hero spacing, lowercase headings).

PAGE_TSX = 'import Nav from "../anti-ai-components/components/Nav";\nimport Hero from "../anti-ai-components/components/Hero";\nimport Button from "../anti-ai-components/components/Button";\nimport Card from "../anti-ai-components/components/Card";\n\n// Complete landing page — concept: {{CONCEPT}}\n// Generated by the Anti-AI Design System. Tension points:\n// - Hero uses --section-top / --section-bottom (asymmetric spacing)\n// - The quote block carries the one 2px border\n// - The middle pricing tier gets the accent border\n// - Headings lowercase. Do not "fix" these.\nexport default function LandingPage() {\n  return (\n    <div style={{ background: "var(--color-surface)", color: "var(--color-text)" }}>\n      <Nav\n        logo="{{LOGO}}"\n        links={[\n          { label: "features", href: "#features" },\n          { label: "pricing", href: "#pricing" },\n          { label: "about", href: "#about" },\n        ]}\n        cta="start"\n      />\n      <Hero\n        title="{{HEADLINE}}"\n        subtitle="{{SUBTITLE}}"\n        primaryCta="{{CTA_BUTTON}}"\n        secondaryCta="see pricing"\n      />\n\n      <section id="features" style={{ maxWidth: 1200, margin: "0 auto", padding: "48px 24px" }}>\n        <h2 style={{ fontFamily: "var(--font-display)", fontSize: 28, letterSpacing: "var(--tracking-display)", marginTop: 0, marginBottom: 24 }}>\n          what you get\n        </h2>\n        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 16 }}>\n          <Card title="{{F1_TITLE}}">{{F1_TEXT}}</Card>\n          <Card title="{{F2_TITLE}}" variant="tension">{{F2_TEXT}}</Card>\n          <Card title="{{F3_TITLE}}">{{F3_TEXT}}</Card>\n        </div>\n      </section>\n\n      <section id="about" style={{ maxWidth: 900, margin: "0 auto", padding: "32px 24px" }}>\n        <blockquote style={{ border: "2px solid var(--color-tension)", borderRadius: "var(--radius-md)", padding: 32, margin: 0 }}>\n          <p style={{ fontFamily: "var(--font-display)", fontSize: 22, lineHeight: 1.4, marginTop: 0, marginBottom: 12 }}>\n            "{{QUOTE}}"\n          </p>\n          <cite style={{ fontFamily: "var(--font-body)", fontSize: 13, color: "var(--color-text-muted)", fontStyle: "normal" }}>\n            — {{QUOTE_AUTHOR}}\n          </cite>\n        </blockquote>\n      </section>\n\n      <section id="pricing" style={{ maxWidth: 1200, margin: "0 auto", padding: "48px 24px" }}>\n        <h2 style={{ fontFamily: "var(--font-display)", fontSize: 28, letterSpacing: "var(--tracking-display)", marginTop: 0, marginBottom: 24 }}>\n          pricing\n        </h2>\n        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 16 }}>\n          {["{{TIER1}}", "{{TIER2}}", "{{TIER3}}"].map((tier, i) => (\n            <div\n              key={tier}\n              style={{\n                background: "var(--color-surface)",\n                border: i === 1 ? "2px solid var(--color-accent)" : "1px solid var(--color-border)",\n                borderRadius: "var(--radius-md)",\n                padding: 24,\n                textAlign: "center",\n              }}\n            >\n              <p style={{ fontFamily: "var(--font-display)", fontSize: 18, marginTop: 0, marginBottom: 8 }}>{tier}</p>\n              <p style={{ fontFamily: "var(--font-body)", fontSize: 13, color: "var(--color-text-muted)", marginBottom: 16 }}>\n                for teams that care\n              </p>\n              <Button variant={i === 1 ? "primary" : "secondary"}>{i === 1 ? "choose" : "pick"}</Button>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      <section style={{ maxWidth: 1200, margin: "0 auto", padding: "64px 24px 96px", textAlign: "center" }}>\n        <h2 style={{ fontFamily: "var(--font-display)", fontSize: 32, letterSpacing: "var(--tracking-display)", marginTop: 0, marginBottom: 16 }}>\n          {{CTA_HEADLINE}}\n        </h2>\n        <Button>{{CTA_BUTTON}}</Button>\n      </section>\n\n      <footer style={{ borderTop: "1px solid var(--color-border)", padding: 24, textAlign: "center" }}>\n        <p style={{ fontFamily: "var(--font-body)", fontSize: 12, color: "var(--color-text-muted)", margin: 0 }}>\n          {{LOGO}} — built with the anti-ai design system. do not remove the tension.\n        </p>\n      </footer>\n    </div>\n  );\n}\n'

