def generate_page(design, brief=None):
    concept = (design or {}).get("concept") or "craft"
    copy = dict(CONCEPT_COPY.get(concept, CONCEPT_COPY["craft"]))
    if brief and isinstance(brief.get("project"), str) and brief["project"].strip():
        first = brief["project"].strip().split(" ")[0].lower()
        if first.isalnum():
            copy["logo"] = first
    page = PAGE_TSX.replace("{{CONCEPT}}", concept)
    for key in sorted(copy.keys(), key=len, reverse=True):
        page = page.replace("{{" + key.upper() + "}}", str(copy[key]))
    return {
        "page/landing-page.tsx": page,
        "page/content.json": json.dumps(copy, indent=2),
    }


def generate_all_pages(design, brief=None):
    files = generate_page(design, brief)
    total_lines = sum(len(c.splitlines()) for c in files.values())
    return {"files": files, "file_count": len(files), "total_lines": total_lines}


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print('usage: pagegen.py \'{"concept": "workbench"}\' [brief json]')
        sys.exit(1)
    design = json.loads(sys.argv[1])
    brief = json.loads(sys.argv[2]) if len(sys.argv) > 2 else None
    result = generate_all_pages(design, brief)
    print(json.dumps({"file_count": result["file_count"], "total_lines": result["total_lines"],
                      "page_preview": result["files"]["page/landing-page.tsx"][:600]}, indent=2))
